CREATE COLUMN TABLE "TEST_AP"."FAA1" ("Code" INTEGER CS_INT NOT NULL , "LineNum" INTEGER CS_INT NOT NULL , "AttrID" INTEGER CS_INT NOT NULL , "AttrName" NVARCHAR(100), "FieldType" NVARCHAR(1), "DefaultVal" NVARCHAR(100), "LogInstanc" INTEGER CS_INT DEFAULT 0, "SnapshotId" INTEGER CS_INT DEFAULT 0, PRIMARY KEY ("Code", "LineNum")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "FAA1_UNIQUE" ON "TEST_AP"."FAA1" ( "Code" ASC, "AttrID" ASC )